-- Rewrite the IAA, Department Hub, Gangs, DevOps and Business Hub guild, role and channel IDs after the backup 58 restore
-- Generated by scripts/generate-restored-guild-migration.mjs from the restore id maps.
-- Forward-only and safe to retry: every rewrite joins old IDs that no longer exist after the first run.

CREATE TABLE IF NOT EXISTS discord_restore_id_map (
  old_id VARCHAR(32) NOT NULL,
  new_id VARCHAR(32) NOT NULL,
  kind VARCHAR(16) NOT NULL,
  restore_ref VARCHAR(64) NOT NULL,
  guild_old VARCHAR(32) NOT NULL,
  guild_new VARCHAR(32) NOT NULL,
  PRIMARY KEY (old_id, restore_ref),
  KEY discord_restore_id_map_new (new_id)
) ENGINE=InnoDB;

DELETE FROM discord_restore_id_map WHERE restore_ref='network-restore-2026-11-11';

-- Cached role lists mirror Discord. Drop roles that were already gone from the backup, then move the rest.
DELETE r FROM discord_guild_roles r JOIN discord_restore_id_map g ON g.old_id=r.guild_id AND g.kind='guild' AND g.restore_ref='network-restore-2026-11-11'
  LEFT JOIN discord_restore_id_map m ON m.old_id=r.role_id AND m.restore_ref='network-restore-2026-11-11' WHERE m.old_id IS NULL;
UPDATE discord_guild_roles r JOIN discord_restore_id_map g ON g.old_id=r.guild_id AND g.kind='guild' AND g.restore_ref='network-restore-2026-11-11'
  JOIN discord_restore_id_map m ON m.old_id=r.role_id AND m.restore_ref='network-restore-2026-11-11' SET r.guild_id=g.new_id, r.role_id=m.new_id;

-- Role-sourced groups, network synchronisation and protected roles.
UPDATE discord_role_sources r JOIN discord_restore_id_map g ON g.old_id=r.guild_id AND g.kind='guild' AND g.restore_ref='network-restore-2026-11-11'
  JOIN discord_restore_id_map m ON m.old_id=r.role_id AND m.restore_ref='network-restore-2026-11-11' SET r.guild_id=g.new_id, r.role_id=m.new_id;
UPDATE network_sync_roles r JOIN discord_restore_id_map g ON g.old_id=r.guild_id AND g.kind='guild' AND g.restore_ref='network-restore-2026-11-11'
  JOIN discord_restore_id_map m ON m.old_id=r.role_id AND m.restore_ref='network-restore-2026-11-11' SET r.guild_id=g.new_id, r.role_id=m.new_id;
UPDATE protected_roles r JOIN discord_restore_id_map g ON g.old_id=r.guild_id AND g.kind='guild' AND g.restore_ref='network-restore-2026-11-11'
  JOIN discord_restore_id_map m ON m.old_id=r.role_id AND m.restore_ref='network-restore-2026-11-11' SET r.guild_id=g.new_id, r.role_id=m.new_id;
UPDATE network_sync_anchors a JOIN discord_restore_id_map m ON m.old_id=a.below_role_id AND m.restore_ref='network-restore-2026-11-11' SET a.below_role_id=m.new_id;
UPDATE network_sync_anchors t JOIN discord_restore_id_map m ON m.old_id=t.guild_id AND m.kind='guild' AND m.restore_ref='network-restore-2026-11-11' SET t.guild_id=m.new_id;
UPDATE network_sync_guild_settings t JOIN discord_restore_id_map m ON m.old_id=t.guild_id AND m.kind='guild' AND m.restore_ref='network-restore-2026-11-11' SET t.guild_id=m.new_id;
UPDATE network_guilds t JOIN discord_restore_id_map m ON m.old_id=t.guild_id AND m.kind='guild' AND m.restore_ref='network-restore-2026-11-11' SET t.guild_id=m.new_id;
UPDATE network_sync_guilds t JOIN discord_restore_id_map m ON m.old_id=t.guild_id AND m.kind='guild' AND m.restore_ref='network-restore-2026-11-11' SET t.guild_id=m.new_id;
UPDATE chain_of_command_config t JOIN discord_restore_id_map m ON m.old_id=t.guild_id AND m.kind='guild' AND m.restore_ref='network-restore-2026-11-11' SET t.guild_id=m.new_id;

-- Agency and DevOps rank ladders.
UPDATE iaa_ranks t JOIN discord_restore_id_map m ON m.old_id=t.role_id AND m.restore_ref='network-restore-2026-11-11' AND m.kind IN ('role') SET t.role_id=m.new_id;
UPDATE iaa_ranks t JOIN discord_restore_id_map m ON m.old_id=t.tier_role_id AND m.restore_ref='network-restore-2026-11-11' AND m.kind IN ('role') SET t.tier_role_id=m.new_id;
UPDATE devops_ranks t JOIN discord_restore_id_map m ON m.old_id=t.role_id AND m.restore_ref='network-restore-2026-11-11' AND m.kind IN ('role') SET t.role_id=m.new_id;

